import{_ as e,o as s,c as t,ag as i}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"科学日报 · 2026-10-28（量子 / 光子学 / 测量诱导干涉仪）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-10-28-quantum.md","filePath":"topics/quantum-physics/science-daily-2026-10-28-quantum.md"}'),c={name:"topics/quantum-physics/science-daily-2026-10-28-quantum.md"};function n(d,o,a,r,l,u){return s(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-10-28-量子-光子学-测量诱导干涉仪" tabindex="-1">科学日报 · 2026-10-28（量子 / 光子学 / 测量诱导干涉仪） <a class="header-anchor" href="#科学日报-·-2026-10-28-量子-光子学-测量诱导干涉仪" aria-label="Permalink to &quot;科学日报 · 2026-10-28（量子 / 光子学 / 测量诱导干涉仪）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> — 第47期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-quantum</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-28-把复杂度从「深层光路」挪到「测量」——400-模压缩光干涉仪绕开损耗墙" tabindex="-1">科学日报 2026-10-28：把复杂度从「深层光路」挪到「测量」——400 模压缩光干涉仪绕开损耗墙 <a class="header-anchor" href="#科学日报-2026-10-28-把复杂度从「深层光路」挪到「测量」——400-模压缩光干涉仪绕开损耗墙" aria-label="Permalink to &quot;科学日报 2026-10-28：把复杂度从「深层光路」挪到「测量」——400 模压缩光干涉仪绕开损耗墙&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ DOI: 10.1126/sciadv.aee5135 ｜ Science Advances (2026)</p></blockquote><ul><li>问题：可扩展干涉仪是<strong>光子量子技术</strong>的核心器件，但其<strong>扩展被光学损耗卡死</strong>——<strong>电路越深、损耗越大</strong>，这是根本性瓶颈。</li><li>本工作：提出并实验演示一种<strong>测量诱导（measurement-induced）架构</strong>的多模压缩光干涉仪。核心思想：<strong>把复杂度从「深层光学网络」转移到「可编程零差测量」</strong>，于是只需在<strong>一层浅、低损耗的平台</strong>上就能实现等效的幺正变换。</li><li>结果： <ul><li>用 <strong>6 模</strong>器件验证原理；</li><li>扩展到 <strong>400 模</strong>干涉仪——<strong>规模远超常规设计</strong>；</li><li>该策略同时给出一条<strong>产生大规模纠缠态</strong>的路径（量子计算/模拟/通信的关键需求）；</li><li>作者定位：测量诱导电路是通往 <strong>NISQ 应用与未来量子优势</strong>的实用路线。</li></ul></li><li>洞察（对本库 <code>quantum-physics</code> × <code>physics</code>）： <ol><li><strong>「把复杂度搬到测量端」＝换通道，而不是造更深的网络</strong> —— 深层光路的损耗随深度累积（不可逆），而测量是可以「事后计算」重组的<strong>可编程自由度</strong>。判据：<strong>当一个物理量随规模变差（损耗随深度增长）时，先问这个复杂度能不能挪到一个「不随规模变差」的通道（这里是测量），而不是硬扩原通道。</strong> 这是本库 <code>physics</code> 模块六（盲人摸象）「物理极限是单通道的极限，多通道可绕过」的量子版。</li><li><strong>与 10-27「涡旋从透镜型改腔型」、今日 10-28 物理板块「紫外调制换材料平台」同族</strong> —— 三条独立论文都指向同一动作：<strong>改路径（架构/平台），不改力度（加功率/加深度）</strong>。可写入 <code>science-news/index.md</code> 的「改路径优先」清单。</li><li><strong>注意措辞克制</strong>：400 模是<strong>规模的跃升</strong>，但作者明确把它定位为<strong>通往</strong> NISQ 应用与量子优势的<strong>路线</strong>，并未宣称已实现量子优势；落库保留「实用路线/原理验证」而非「已达成」。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第47期 科学板块</p></blockquote><p>关键词：科学日报第47期、测量诱导架构、measurement-induced、多模压缩光干涉仪、squeezed light、光路深度损耗瓶颈、可编程零差测量 homodyne、浅层低损耗平台、6 模验证、400 模扩展、大规模纠缠态、NISQ、量子优势路线、把复杂度搬到测量端、换通道而非加深网络、改路径不改力度</p><p>关联：<code>topics/quantum-physics/index.md</code>、<code>topics/physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-10-25-quantum.md</code>、<code>topics/physics/science-daily-2026-10-28-physics.md</code>（紫外集成调制器）、<code>topics/ai-brain/index.md</code></p>',10)])])}const m=e(c,[["render",n]]);export{g as __pageData,m as default};
